-- seed_company_logo.sql — Seed the ArxDev company_logo app_config value.
-- Split out from seed_test_data.sql because the value is a large base64 data URI that
-- would swamp that file's diff on every change. Run this AFTER seed_test_data.sql
-- (which clears app_config on every run). Safe to run repeatedly.

DELETE FROM app_config WHERE setting_key = 'company_logo';
INSERT INTO app_config (setting_key, setting_value, updated_at) VALUES
    ('company_logo', 'data:image/png;base64,', '2020-01-01T00:00:00');
